-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the trigger function raises (1/0) AFTER its NULL / '{}' early return -- first sign-in must stay unaffected
-- targets: c25d
-- expect: green
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._reject_feature_override_above_tier()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_plan_tier text;
  v_key       text;
  v_entry     jsonb;
  v_min_tier  text;
BEGIN
  IF NEW.feature_overrides IS NULL OR NEW.feature_overrides = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  PERFORM 1/0;

  IF TG_OP = 'UPDATE' AND NEW.feature_overrides IS NOT DISTINCT FROM OLD.feature_overrides THEN
    RETURN NEW;
  END IF;

  SELECT p.tier INTO v_plan_tier
    FROM public.plans p
   WHERE p.id = NEW.plan_id;

  -- jsonb_each raises 22023 when feature_overrides is not an object.
  FOR v_key, v_entry IN
    SELECT e.key, e.value FROM jsonb_each(NEW.feature_overrides) AS e
  LOOP
    -- Only the entries this write adds or changes are validated.
    IF TG_OP = 'UPDATE'
       AND jsonb_typeof(OLD.feature_overrides) = 'object'
       AND (OLD.feature_overrides -> v_key) IS NOT DISTINCT FROM v_entry THEN
      CONTINUE;
    END IF;

    v_min_tier := NULL;
    SELECT fd.min_tier INTO v_min_tier
      FROM public.feature_definitions fd
     WHERE fd.key = v_key;

    IF public._override_above_tier(v_key, v_min_tier, v_plan_tier, v_entry) THEN
      RAISE EXCEPTION 'feature_override_above_tier: % requires %; plan tier is %',
        v_key, v_min_tier, COALESCE(v_plan_tier, 'none')
        USING ERRCODE = '23514';
    END IF;
  END LOOP;

  RETURN NEW;
END
$$;

DO $proof$
BEGIN
  IF NOT (position('PERFORM 1/0' in pg_get_functiondef('public._reject_feature_override_above_tier()'::regprocedure)) > position('IF NEW.feature_overrides IS NULL' in pg_get_functiondef('public._reject_feature_override_above_tier()'::regprocedure))) THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('1/0 after the early return') AS mutation;
